style.css:
@-moz-document domain("csdn.net") {
/* ============================================================
     CSDN Dark
     CSDN (csdn.net + blog.csdn.net + so./ask./bbs./download.) is
     built on hardcoded colors, not a design-token system, so the
     theme works by (1) painting the page base + content cards
     dark, (2) neutralizing the many white containers, and (3)
     fully recoloring code blocks + the highlight.js syntax
     palette, which is the core surface on a developer site.
     GitHub-dark-ish palette throughout.
     ============================================================ */

  :root {
    color-scheme: dark;
    --csdn-base: #14181d;
    --csdn-elev: #1c2128;
    --csdn-elev2: #21262d;
    --csdn-chrome: #0d1117;
    --csdn-border: #2d333b;
    --csdn-border-soft: #262c33;
    --csdn-text: #e6edf3;
    --csdn-text-2: #c4cdd6;
    --csdn-muted: #8b949e;
    --csdn-link: #5fb0e6;
    --csdn-link-hover: #9bd4ff;
    --csdn-code-bg: #161b22;
    --csdn-red: #f0795c;
  }

  /* ---------- Base ---------- */
  html,
  body {
    background-color: var(--csdn-base) !important;
    color: var(--csdn-text-2) !important;
  }
  /* blog articles can carry an author-chosen "skin" that paints a light
     full-page raster (e.g. skin-1024 bg.gif) as a body background-IMAGE —
     drop it so the dark base shows through (bg-color audit misses url() bgs) */
  body.nodata {
    background-image: none !important;
  }

  /* Soften every light border into a subtle dark one */
  * {
    border-color: var(--csdn-border-soft) !important;
  }

  /* ---------- Broad white-surface neutralizer ----------
     Most CSDN section wrappers carry a hardcoded white bg.
     Flatten them to transparent so the dark base shows through,
     then re-establish solid dark on the real cards + floating
     surfaces below (so nothing bleeds through). */
  body div[class],
  body section[class],
  body aside[class],
  body main,
  body article {
    background-color: transparent !important;
  }

  /* ---------- Page wrappers / layout ---------- */
  #app,
  .layout-container,
  .home_wrap_box,
  #mainBox,
  main,
  .container,
  .blog_container,
  .blog_container_aside,
  .recommend-box,
  .recommend-right,
  .article_content,
  #content_views,
  .toc-box {
    background-color: transparent !important;
    color: var(--csdn-text-2) !important;
  }
  /* article TOC ("目录") active item ships a near-white highlight
     (rgb 240,240,245) — recolor to a dark surface + red accent text,
     scoped to the toc-box so it can't catch unrelated .active items */
  .toc-box li.active,
  .toc-box li.active a {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-red) !important;
  }

  /* ---------- Elevated cards / panels ---------- */
  .blog-content-box,
  #asideProfile,
  .aside-box,
  .recommend-item-box,
  .recommend-card,
  .first-recommend-box,
  .recommend-ad-box,
  .blog_extension,
  .article-info-box,
  .comment-box,
  .comment-list-box,
  .more-toolbox-new,
  .calendar,
  .calendar-content-item,
  .card,
  .Community,
  .feed-card,
  .blink-card,
  .floor-item,
  .item,
  .nav-second,
  .kind_list,
  .left-box,
  .right-box,
  .container-fluid,
  .csdn-tracking-statistics,
  .csdn-toolbar-plugin,
  .layout-sidebar-aside,
  .csdn-common-logo-box {
    background-color: var(--csdn-elev) !important;
    border-color: var(--csdn-border) !important;
    color: var(--csdn-text-2) !important;
  }

  /* Slightly lighter blue promo tiles -> elevated */
  .project-item,
  a.project-item {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-text-2) !important;
  }
  /* white pill button inside promo tiles */
  .project-item p.btn,
  .project-bottom .btn,
  .project-bottom p.btn {
    background-color: var(--csdn-link) !important;
    color: #0d1117 !important;
    border-color: var(--csdn-link) !important;
  }

  /* In-article reference / link cards + recommend rows + tables */
  .link-card-box,
  .link-card,
  span.link-card-box,
  .recommend-box .recommend-item-box,
  .blog-content-box table,
  .blog-content-box tr,
  .recommend-card-box,
  .more-toolbox-new .toolbox-list,
  .csdn-edu-comment,
  .insert-card,
  .csdn-blog-text-card {
    background-color: var(--csdn-elev) !important;
    color: var(--csdn-text-2) !important;
    border-color: var(--csdn-border) !important;
  }
  .link-card-box .link-title,
  .link-card-box .link-link,
  .recommend-item-box .tit,
  .recommend-item-box .dec,
  .recommend-item-box .blog-text {
    color: var(--csdn-text-2) !important;
  }

  /* Paid-column promo card embedded in articles */
  #blogColumnPayAdvert,
  .column-group,
  .column-group-item,
  .column-group-item-one,
  .column-info,
  .profile-intro-name-years,
  .profile-intro-name-boxFooter {
    background-color: var(--csdn-elev) !important;
    color: var(--csdn-text-2) !important;
    border-color: var(--csdn-border) !important;
  }
  #blogColumnPayAdvert .tit,
  #blogColumnPayAdvert .title,
  .column-group-item .tit {
    color: var(--csdn-text) !important;
  }
  #blogColumnPayAdvert .dec,
  .column-group-item .dec,
  .profile-intro-name-years {
    color: var(--csdn-muted) !important;
  }

  /* "原创 / 转载" article-type badge — tone the pink chip for dark */
  .article-type-text,
  .article-type-text.original,
  .article-type-text.fovorite,
  .article-bar-top .article-type {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-link) !important;
  }

  /* ---------- Fixed / floating chrome (must stay opaque) ---------- */
  #csdn-toolbar,
  #toolbarBox,
  .toolbar-container,
  .csdn-toolbar,
  .home_box_nav,
  .blog_nav,
  .toolbar-container-sidebar-www,
  .csdn-side-toolbar,
  .more-toolbox-new,
  .pop-box,
  .toolbar-search-container,
  .dropdown-menu,
  .el-dropdown-menu,
  .toolbar-menu,
  .nav-second-floor,
  .toolbar-btn-loginfun {
    background-color: var(--csdn-chrome) !important;
    border-color: var(--csdn-border) !important;
    color: var(--csdn-text) !important;
  }

  /* keep the fixed header reliably solid */
  #csdn-toolbar {
    background-color: var(--csdn-chrome) !important;
  }

  /* Toolbar search autocomplete flyout: the .toolbar-search-drop-menu
     (associate-word) panel + its .drop-menu-list are flattened to
     transparent by the broad neutralizer, so the open suggestion list
     bleeds the page content (carousel + feed) through behind its rows.
     Re-establish a solid dark surface + a hover state. */
  body div.toolbar-search-drop-menu,
  body div.associate-word-drop-menu,
  .toolbar-search-drop-menu .drop-menu-list,
  .drop-menu-list,
  .drop-menu-list li {
    background-color: var(--csdn-chrome) !important;
    color: var(--csdn-text-2) !important;
  }
  .drop-menu-list li:hover,
  .drop-menu-list li.active {
    background-color: var(--csdn-elev2) !important;
  }
  /* The "创作" (write) toolbar flyout is the .csdn-toolbar-plugin panel; it is
     listed in the elevated-cards block but the broad neutralizer
     (body div[class], higher specificity) flattens it to transparent, so the
     open flyout header bleeds the nav chips + page through. Boost specificity
     to re-seat its opaque chrome surface. */
  body div.csdn-toolbar-plugin,
  body div.csdn-toolbar-plugin-container {
    background-color: var(--csdn-chrome) !important;
  }

  /* Toolbar dropdown menus + their items */
  .menus-view_content__inner,
  .menus-view,
  .menus-item,
  .menus-item p,
  .menus-item a,
  .toolbar-menu-list,
  .toolbar-menu-list li {
    background-color: var(--csdn-chrome) !important;
    color: var(--csdn-text-2) !important;
  }
  .menus-item:hover,
  .menus-item a:hover,
  .toolbar-menu-list li:hover {
    background-color: var(--csdn-elev2) !important;
  }
  /* toolbar top-nav dropdown items (.toolbar-subMenu — e.g. "更多" holding
     会议/学习) paint a near-white rgb(240,240,245) highlight on the trigger
     box when hovered/open (audit-blind: :hover state + 67px wide, under the
     big() threshold). Repaint the hover box + its flyout to dark chrome. */
  .toolbar-subMenu-box:hover,
  .toolbar-subMenu:hover .toolbar-subMenu-box,
  .toolbar-subMenu-list,
  .toolbar-subMenu-list li:hover {
    background-color: var(--csdn-chrome) !important;
  }

  /* Article action-bar "觉得还不错？" nudge bubble: the .tool-active-list
     speech bubble is drawn entirely by white ::before (body) + ::after
     (arrow) pseudo-elements (audit-blind — pseudos, and the box is only
     32px tall). Repaint both dark so its light label is legible. */
  .tool-active-list::before,
  .tool-active-list::after {
    background-color: var(--csdn-elev2) !important;
  }
  .tool-active-list .text,
  .tool-active-list .text * {
    color: var(--csdn-text-2) !important;
  }

  /* Side copyright/contact footer popover */
  .csdnside-copyright-footer-contact,
  .csdnside-copyright-footer-contact .work-time-btn,
  .csdnside-copyright-footer-contact .link {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-text-2) !important;
  }

  /* ---------- Headings + body text ---------- */
  h1, h2, h3, h4, h5, h6,
  .title-article,
  .article-title,
  .blog-title,
  .text-title,
  .title,
  .name,
  .user-name,
  .nick-name,
  .username,
  b, strong {
    color: var(--csdn-text) !important;
  }

  p, span, li, td, th, dd, dt, label, div,
  .text,
  .summary,
  .desc,
  .blog-text,
  .markdown_views,
  #content_views,
  #content_views p,
  #content_views li,
  #content_views span,
  .comment-content {
    color: var(--csdn-text-2) !important;
  }

  /* Muted metadata (read counts, dates, tags) */
  .read-count,
  .time,
  .date,
  .read-num,
  .num,
  .blog-tags-box span,
  .tag,
  .meta,
  .info,
  .recommend-item-box .desc,
  .article-info-box .time,
  .comment-time,
  .text-gray,
  .gray {
    color: var(--csdn-muted) !important;
  }
  /* search-result download-size metadata ships a hardcoded dark grey
     (#555666) via a higher-specificity site rule — lift to muted, and set
     the fill too in case the site drives it through -webkit-text-fill-color */
  body .so-items-bottom .btm-lt .download-size,
  body .so-result .download-size,
  body .download-size {
    color: var(--csdn-muted) !important;
    -webkit-text-fill-color: var(--csdn-muted) !important;
  }

  /* ---------- Links ---------- */
  a,
  a:visited,
  #content_views a {
    color: var(--csdn-link) !important;
  }
  a:hover,
  #content_views a:hover {
    color: var(--csdn-link-hover) !important;
  }
  /* keep nav/card links that should look like text */
  .toolbar-container a,
  .home_box_nav a,
  .feed-card a.title,
  .blog-content-box a.title {
    color: var(--csdn-text) !important;
  }
  .toolbar-container a:hover,
  .home_box_nav a:hover {
    color: var(--csdn-link-hover) !important;
  }

  /* ---------- Inputs / forms / search ---------- */
  input,
  textarea,
  select,
  .toolbar-search,
  .toolbar-search-input,
  .comment-edit-box,
  .comment-operate-box {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-text) !important;
    border-color: var(--csdn-border) !important;
  }
  input::placeholder,
  textarea::placeholder {
    color: var(--csdn-muted) !important;
    opacity: 1 !important;
  }
  input::-webkit-input-placeholder,
  textarea::-webkit-input-placeholder {
    color: var(--csdn-muted) !important;
  }

  /* ---------- Buttons ---------- */
  .btn,
  button,
  .button,
  .btn-comment,
  .submit-btn,
  .more-btn {
    border-color: var(--csdn-border) !important;
  }

  /* ============================================================
     CODE BLOCKS — the core developer surface.
     CSDN lets authors pick a "skin" (atom-one-light/-dark,
     github, etc.) so token colors vary wildly and the light
     skins are unreadable on dark. Force every code block to the
     dark base + apply one consistent, legible syntax palette,
     overriding whatever skin class is on the wrapper.
     ============================================================ */
  pre,
  pre.hljs,
  pre code,
  pre code.hljs,
  .hljs,
  .htmledit_views pre,
  .htmledit_views code,
  code.hljs,
  #content_views pre,
  .markdown_views pre {
    background: var(--csdn-code-bg) !important;
    background-color: var(--csdn-code-bg) !important;
    color: #c9d1d9 !important;
    border-color: var(--csdn-border) !important;
  }

  /* CSDN's interactive code widgets (the "运行项目/登录复制" blocks that show a
     language label like "undefined"/"groovy"/"erlang-repl") drive the <code>
     text through a rule that ALSO sets -webkit-text-fill-color to a dark
     #4f4f4f — which overrides our plain `color` at RENDER time, so plain /
     unhighlighted code lines ship dark-on-dark (audit-blind: text-fill-color).
     Re-assert a readable base color with higher specificity and pin the
     text-fill so it can't override us. */
  .markdown_views pre code,
  .markdown_views pre code.hljs,
  #content_views pre code,
  #content_views pre code.hljs,
  pre.set-code-show code,
  pre.set-code-show code.hljs {
    color: #c9d1d9 !important;
    -webkit-text-fill-color: #c9d1d9 !important;
  }
  /* keep every syntax-token span rendering its OWN palette color — make the
     text-fill follow `color` so the pinned base fill above can't bleed in */
  pre code span,
  .hljs span,
  pre code [class*="hljs-"] {
    -webkit-text-fill-color: currentColor !important;
  }

  /* inline code inside prose */
  #content_views p code,
  #content_views li code,
  p code,
  li code {
    background-color: var(--csdn-elev2) !important;
    color: #e6a98c !important;
    border-color: var(--csdn-border) !important;
  }

  /* code line numbers — the gutter container (ul.pre-numbering) ships a
     near-white #fafafa bg (it's a <ul>, so the div/section neutralizer misses
     it), leaving the numbers in white cells beside the dark code. Paint the
     gutter to the code base and mute the numbers. */
  ul.pre-numbering,
  .pre-numbering {
    background-color: var(--csdn-code-bg) !important;
    border-color: var(--csdn-border) !important;
  }
  .hljs-ln-numbers,
  .hljs-ln-n,
  .pre-numbering li,
  .line-numbers-rows span {
    color: #6e7681 !important;
    background-color: transparent !important;
  }

  /* code copy / toolbar button */
  pre .hljs-button,
  .hljs-button,
  .code-toolbar,
  .hljs-comment-copy,
  .copy-code-btn {
    color: var(--csdn-muted) !important;
    background-color: transparent !important;
  }
  pre .hljs-button:hover,
  .hljs-button:hover {
    color: var(--csdn-link) !important;
  }

  /* ---- highlight.js syntax palette (GitHub-dark) ---- */
  .hljs-comment,
  .hljs-quote {
    color: #8b949e !important;
    font-style: italic;
  }
  .hljs-keyword,
  .hljs-selector-tag,
  .hljs-literal,
  .hljs-type,
  .hljs-deletion,
  .hljs-subst {
    color: #ff7b72 !important;
  }
  .hljs-string,
  .hljs-meta-string,
  .hljs-regexp,
  .hljs-addition {
    color: #a5d6ff !important;
  }
  .hljs-number,
  .hljs-symbol,
  .hljs-bullet,
  .hljs-link {
    color: #79c0ff !important;
  }
  .hljs-title,
  .hljs-function .hljs-title,
  .hljs-section,
  .hljs-name {
    color: #d2a8ff !important;
  }
  .hljs-attr,
  .hljs-attribute,
  .hljs-variable,
  .hljs-template-variable,
  .hljs-selector-attr,
  .hljs-selector-pseudo,
  .hljs-selector-class,
  .hljs-selector-id {
    color: #79c0ff !important;
  }
  .hljs-built_in,
  .hljs-builtin-name,
  .hljs-class .hljs-title,
  .hljs-meta {
    color: #ffa657 !important;
  }
  .hljs-operator,
  .hljs-punctuation,
  .hljs-params {
    color: #c9d1d9 !important;
  }
  .hljs-tag {
    color: #7ee787 !important;
  }
  .hljs-emphasis { font-style: italic; }
  .hljs-strong { font-weight: bold; }

  /* ---------- Markdown content extras ---------- */
  #content_views blockquote,
  .markdown_views blockquote {
    background-color: var(--csdn-elev) !important;
    border-left-color: var(--csdn-border) !important;
    color: var(--csdn-muted) !important;
  }
  #content_views table,
  .markdown_views table {
    border-color: var(--csdn-border) !important;
  }
  #content_views th,
  .markdown_views th {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-text) !important;
    border-color: var(--csdn-border) !important;
  }
  #content_views td,
  .markdown_views td {
    color: var(--csdn-text-2) !important;
    border-color: var(--csdn-border) !important;
  }
  #content_views tr:nth-child(2n),
  .markdown_views tr:nth-child(2n) {
    background-color: var(--csdn-elev) !important;
  }
  #content_views hr {
    border-color: var(--csdn-border) !important;
    background-color: var(--csdn-border) !important;
  }

  /* ---------- Tags / chips ---------- */
  .tag-list a,
  .blog-tags-box a,
  .tags a,
  .label,
  .chip {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-text-2) !important;
    border-color: var(--csdn-border) !important;
  }
  /* article-footer tag pills (.tag-link-new — #java / #python / #算法) ship a
     pale-blue rgb(229,241,255) bg with blue link text = pale-on-pale on dark
     (audit-blind: ~49-66px wide pills under the big() threshold). Darken to an
     elevated surface, keep the blue tag-link text. */
  .tag-link-new,
  .article-footer-pill-list a {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-link) !important;
    border-color: var(--csdn-border) !important;
  }
  /* author-card "博客等级" blog-level badge (.profile-intro-name-leve) ships a
     light-grey rgb(245,246,247) pill; our lightened text then goes light-on-
     light (audit-blind: 84×21 pill). Darken it. */
  .profile-intro-name-leve {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-text-2) !important;
  }

  /* ---------- Search-results filters / sort tabs (all states) ---------- */
  .so-search,
  .so-result,
  .search-list-con,
  .so-sort,
  .sort,
  .common-lt,
  .so-tab,
  .toolbar-tab,
  .tab-list,
  .search-input-box {
    background-color: transparent !important;
    color: var(--csdn-text-2) !important;
  }
  .sort .item,
  .common-lt span,
  .so-sort .item,
  .tab-list .tab {
    color: var(--csdn-muted) !important;
  }
  .sort .active,
  .common-lt .active,
  .so-sort .item.active,
  .tab-list .tab.active,
  .so-tab .active {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-link) !important;
  }
  /* so.csdn.net "相关搜索" related-term chips: the first (hot) chip is a
     classless .so-hot-words li with a hardcoded white bg (92×28 — below the
     audit height threshold, so audit-blind) carrying pale-blue link text
     that washes out on white. Darken every chip uniformly to an elevated
     surface so the blue term text reads. */
  .so-hot-words ul li,
  .so-hot-words .hw-bd li {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-text-2) !important;
    border-color: var(--csdn-border) !important;
  }

  /* search submit button — brand red, white glyph */
  #toolbar-search-button,
  .so-search-btn,
  .search-btn {
    background-color: #d6492b !important;
    color: #ffffff !important;
    border-color: #d6492b !important;
  }

  /* VIP / 会员 gold badge — keep brand gold, dark legible text */
  .vip-tag,
  .vip-flag,
  .member-tag,
  .icon-vip {
    color: #1a1d21 !important;
  }

  /* Secondary outline buttons (私信 / 关注专栏 etc.) — dark surface, blue label */
  .bt-button,
  a.bt-button,
  .personal-letter,
  .article-column-bt,
  .articleColumnFreeB,
  .tool-attend.tool-bt-button,
  .item-target.article-column-bt {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-link) !important;
    border-color: var(--csdn-border) !important;
  }

  /* ---------- Brand accent (CSDN red) — refined for dark ----------
     CSDN's primary CTAs use a saturated #fc5531 red. Keep the brand
     identity but settle it onto the dark palette and keep label text
     bright white for a readable, intentional CTA. */
  .csdn-toolbar-loginbtn,
  a.csdn-toolbar-loginbtn,
  .csdn-toolbar-regbtn,
  .toolbar-btn-reg,
  .toolbar-btn-write,
  .toolbar-btn-write-new,
  .personal-watch,
  a.personal-watch,
  a.personal-watch.bt-button,
  .bt-button.personal-watch,
  .tool-attend.tool-bt-atten,
  a.tool-bt-atten,
  .btn-red,
  .btn-follow,
  .follow-btn,
  .attention-box .attention,
  .login-box .btn,
  button.runner-btn {
    background-color: #d6492b !important;
    color: #ffffff !important;
    border-color: #d6492b !important;
  }
  /* keep any nested label/icon inside a brand-red CTA white */
  .csdn-toolbar-loginbtn *,
  .csdn-toolbar-regbtn *,
  .toolbar-btn-write *,
  .personal-watch *,
  button.runner-btn * {
    color: #ffffff !important;
  }

  /* ---------- White gradient fades (expand-all / read-more masks) ----------
     CSDN paints a white→transparent linear-gradient over the bottom of the
     category-column list ("展开全部"), collapsed article bodies ("阅读全文")
     and similar widgets. The fade is a background-IMAGE (the bg-color
     neutralizer leaves it untouched), so remap each fade to fall toward the
     dark page base instead of bright white. */
  .flexible-btn-new,
  .hide-article-box,
  .hide-article-pos,
  .hide-preCode-box,
  .readall_box,
  .tool-active-list .read-all {
    background-image: linear-gradient(rgba(20, 24, 29, 0), var(--csdn-base) 62%) !important;
  }
  .flexible-btn-new {
    color: var(--csdn-link) !important;
  }
  /* home category chip carousel edge fades: the horizontal-scroll nav
     (.menus-view_prev / _next) paints a white→transparent linear-gradient
     mask over the left/right chips to hint "more categories" (a background-
     IMAGE, so the bg-color audit misses it, and each mask is <52px wide so
     the big() height/width filter skips it too). Remap the white stop to the
     dark page base so the fade blends into the chip row. */
  .menus-view_next {
    background-image: linear-gradient(90deg, rgba(20, 24, 29, 0), var(--csdn-base) 52px) !important;
  }
  .menus-view_prev {
    background-image: linear-gradient(270deg, rgba(20, 24, 29, 0), var(--csdn-base) 32px) !important;
  }
  /* code-block header InsCode runner-button strip: a .mask child paints a
     horizontal white→transparent fade (background-IMAGE, audit-blind) at the
     strip edge — drop it so the dark code header stays clean */
  .ins-code-runner-btn .mask,
  div.ins-code-runner-btn > .mask {
    background-image: none !important;
  }

  /* ---------- AtomGit / GitCode "quick-app" promo card (article sidebar) ----------
     A large promo tile whose .gitcode-work-space carries a near-white
     background-IMAGE gradient (invisible to the bg-color audit). Flatten it
     to a dark elevated surface and lighten its light-on-white copy. */
  body div.gitcode-quick-app,
  body div.gitcode-quick-app.light,
  body div.gitcode-qc-left-box,
  body div.gitcode-work-space {
    background-color: var(--csdn-elev) !important;
    background-image: none !important;
    border-color: var(--csdn-border) !important;
  }
  body div.gitcode-quick-app,
  body div.gitcode-quick-app * {
    color: var(--csdn-text-2) !important;
  }
  /* the promo's header banner is a raster PNG with a baked-in light
     background — drop it so its caption sits on the dark card */
  body div.gitcode-quick-app .csdn-card-content {
    background-image: none !important;
  }

  /* ---------- AI search card ("开发者首选的 AI 搜索引擎") ----------
     The AI-search promo wraps its dark textarea in a .chat-input-main box
     painted white via a background-IMAGE gradient (bg-color transparent, so
     audit-blind). Flatten it to a dark elevated surface so only the textarea
     + brand-purple submit button read on it. On the so.csdn.net results page
     this card now renders inside an ai.csdn.net/chat IFRAME, where
     .chat-input-main has NO .ai-search-card ancestor (that wrapper lives in
     the parent document) — so match .chat-input-main standalone too, else the
     iframe card ships bright white. */
  body div.ai-search-card,
  body .ai-search-card .chat-input-main,
  .chat-input-main {
    background-color: var(--csdn-elev) !important;
    background-image: none !important;
    border-color: var(--csdn-border) !important;
  }

  /* tiny white ::before slivers on article/profile asides — neutralize them */
  #aside-content::before,
  #aside-content::after,
  .aside-common-box-content.aside-box-fold::before,
  .aside-common-box-content.aside-box-fold::after {
    background-color: transparent !important;
  }

  /* ---------- Blog-article "skin" raster bars ----------
     When an author applies a CSDN skin (skin-1024 etc.), the article aside
     section headers (.aside-title — 最新评论/大家在看/最新文章/上下篇) and the
     comment-form title (.title-box) render a light bg-nav.png / comment-title
     raster as a background-IMAGE. The bg-color audit misses url() images, so
     these ship as bright white bars. Drop the raster, keep the title text. */
  h3.aside-title,
  .aside-title,
  .comment-box .title-box,
  div.title-box {
    background-image: none !important;
    background-color: transparent !important;
    color: var(--csdn-text) !important;
  }

  /* aside "最新评论" comment previews use solid-white ::before (the "..."
     ellipsis indicator) + ::after (fade mask) pseudo-elements (bg-color
     audit-blind) — they paint a bright "..." sliver bottom-right on dark.
     Remap both to the page base so they blend invisibly. */
  .aside-content .newcomment-list li p.comment::before,
  .aside-content .newcomment-list li p.comment::after,
  .newcomment-list li p.comment.ellipsis::before,
  .newcomment-list li p.comment.ellipsis::after {
    background-color: var(--csdn-base) !important;
    background-image: none !important;
    color: var(--csdn-muted) !important;
  }

  /* ---------- 问答 (ask.csdn.net) ----------
     The Q&A subdomain ships a light active channel pill, a white
     leaderboard header, and a selected filter tag whose dark text
     (driven by -webkit-text-fill-color) goes dark-on-dark. */
  .channelList li.cur,
  .channelList li.active {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-text) !important;
  }
  .tag_name_item.currentTagName,
  .tag_list_box .currentTagName {
    color: var(--csdn-link) !important;
    -webkit-text-fill-color: var(--csdn-link) !important;
  }
  .ask-urgent-list h4 {
    background-color: var(--csdn-elev) !important;
    color: var(--csdn-text) !important;
  }

  /* ---------- User profile page "skin" background ----------
     Profile pages render a user-chosen "skin" as a full-page light
     background-IMAGE on .skin3-template (e.g. user-skin-White) plus a
     light .user-profile-head cover banner. With our transparent content
     containers the light image shows through behind light text and makes
     the whole profile unreadable — strip the skin image, paint dark. */
  .skin3-template,
  .skin-number,
  [class*="user-skin"],
  .user-profile-head {
    background-image: none !important;
    background-color: var(--csdn-base) !important;
  }
  /* the "原力等级" achievement / influence card (active state is white) */
  .user-influence-list,
  .user-influence-list.active,
  .aside-common-box-achievement li {
    background-color: var(--csdn-elev) !important;
    color: var(--csdn-text-2) !important;
    border-color: var(--csdn-border) !important;
  }

  /* ---------- passport.csdn.net login / register page ----------
     The login page paints a full-viewport decorative isometric-city
     illustration as a background-IMAGE on .passport-container (bg-color
     transparent, so audit-blind), and the .login-box / .passport-main card
     is flattened to transparent by the broad neutralizer — the login form
     (titles, tab labels, "扫码登录" copy) then floats unreadably over the
     busy light illustration. Drop the raster and re-seat the card as a
     solid dark elevated surface. Higher specificity (body div.…) so it
     wins over the equal-specificity neutralizer by source order. */
  .passport-container {
    background-image: none !important;
    background-color: var(--csdn-base) !important;
  }
  body div.passport-main,
  body div.login-box,
  body div.passport-box,
  body div.login-content,
  body div.login-form {
    background-color: var(--csdn-elev) !important;
    border-color: var(--csdn-border) !important;
    color: var(--csdn-text-2) !important;
  }
  .login-box .title,
  .passport-main .title {
    color: var(--csdn-text) !important;
  }
  /* "上次登录/扫码登录更方便" last-login hint pill above the login tabs ships a
     warm cream rgb(254,247,240) bg with pale text — light-on-light (audit-blind:
     120×22 pill under the big() threshold). Repaint dark + its down-arrow pseudo. */
  .last-login-way {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-text-2) !important;
  }
  .last-login-way::before,
  .last-login-way::after {
    background-color: var(--csdn-elev2) !important;
    border-top-color: var(--csdn-elev2) !important;
  }

  /* ---------- Element UI cards (download.csdn.net / 文库 + Vue pages) ----------
     The 文库/download frontend is built on Element UI; its .el-card panels
     (e.g. the "资源创作成就榜" leaderboard) ship a hardcoded white surface. */
  .el-card,
  .el-card__body,
  .el-card__header,
  .el-card.is-never-shadow,
  .el-tabs__content,
  .el-collapse-item__content {
    background-color: var(--csdn-elev) !important;
    border-color: var(--csdn-border) !important;
    color: var(--csdn-text-2) !important;
  }
  .el-card__body ul > li,
  .el-card__body > ul > li {
    background-color: transparent !important;
    color: var(--csdn-text-2) !important;
  }

  /* download.csdn.net "新版内容上线啦" onboarding modal: .right-content paints
     a white raster panel (bg-IMAGE, audit-blind) and all the title/feature
     text is real DOM that our theme lightens — light-on-white = unreadable.
     Flatten the panel to a dark surface so the light copy + colored feature
     icons read; brand the CTA. */
  .dialog-tip,
  .dialog-tip .right-content,
  .dialog-tip .left-content {
    background-image: none !important;
    background-color: var(--csdn-elev) !important;
  }
  .dialog-tip .title {
    color: var(--csdn-text) !important;
  }
  .dialog-tip .text,
  .dialog-tip .btn {
    color: var(--csdn-text-2) !important;
  }
  /* the left panel is a decorative cube-animation <video> with a baked-in
     light background — hide it so the flattened dark left panel stays clean */
  .dialog-tip .left-content video {
    display: none !important;
  }

  /* ---------- Download-recommend feed (blog list / 404 / column pages) ----------
     The .feed.floatR recommend list renders each row (li.pub_recom_item)
     on a hardcoded white surface with faint grey titles — darken the rows
     and lift the text. */
  .pub_recom_item,
  .pub_recom_item.download,
  .pub_recommend > li {
    background-color: var(--csdn-elev) !important;
    border-color: var(--csdn-border) !important;
    color: var(--csdn-text-2) !important;
  }
  .pub_recom_item .tit,
  .pub_recom_item h3,
  .pub_recom_item a,
  .pub_recom_item .desc {
    color: var(--csdn-text-2) !important;
  }

  /* edu.csdn.net lecturer-card light divider borders */
  #lecturer-sug .lecturer-sug-bottom span.border {
    border-color: var(--csdn-border) !important;
  }
  /* edu.csdn.net toolbar dropdown toggles — dark text (via fill) on dark chrome */
  .edu-toolbar .edu-submenu-dropdown-toggle,
  .edu-toolbar-item button {
    color: var(--csdn-text) !important;
    -webkit-text-fill-color: var(--csdn-text) !important;
  }

  /* bbs.csdn.net (社区) banner quick-link cards — white with light text */
  .bbs-banner_links li {
    background-color: var(--csdn-elev) !important;
    background-image: none !important;
    border-color: var(--csdn-border) !important;
    color: var(--csdn-text-2) !important;
  }

  /* ---------- Images / avatars keep their own pixels ---------- */
  img,
  .avatar,
  .user-avatar {
    background-color: transparent !important;
  }

  /* ---------- Home left-sidebar nav icons ----------
     The www.csdn.net left sidebar (.layout-menus) renders each nav
     glyph as a monochrome near-BLACK raster <img> (首页/博客/下载/学习/
     社区 + 订阅/关注/收藏/历史/会员中心/创作中心/我的算力). On the dark
     sidebar these are dark-on-dark and nearly invisible. They carry no
     class/attr to target, so we recolor by their stable CDN filenames:
     invert the black pixels to a readable muted light. The COLORED brand
     icons (模型市场/AI搜索/AtomGit/InsCode/技术会议) are NOT in this list,
     so they keep their original colors. */
  .layout-menus .layout-menu-item_icon img[src*="20241216111623"],
  .layout-menus .layout-menu-item_icon img[src*="20241216111636"],
  .layout-menus .layout-menu-item_icon img[src*="20241216111629"],
  .layout-menus .layout-menu-item_icon img[src*="20250113040415"],
  .layout-menus .layout-menu-item_icon img[src*="20241216111644"],
  .layout-menus .layout-menu-item_icon img[src*="20241216025916"],
  .layout-menus .layout-menu-item_icon img[src*="20241216025921"],
  .layout-menus .layout-menu-item_icon img[src*="20241216025925"],
  .layout-menus .layout-menu-item_icon img[src*="20241216025927"],
  .layout-menus .layout-menu-item_icon img[src*="20241216025930"],
  .layout-menus .layout-menu-item_icon img[src*="20241216025933"],
  .layout-menus .layout-menu-item_icon img[src*="b218ee9788964cb681ba51bf5089b2dc"] {
    filter: invert(1) brightness(0.85) !important;
  }
  /* active item glyph stays a touch brighter */
  .layout-menus .layout-menu-item.active .layout-menu-item_icon img[src*="20241216111623"] {
    filter: invert(1) brightness(1) !important;
  }

  /* ---------- Scrollbar ---------- */
  ::-webkit-scrollbar { width: 12px; height: 12px; }
  ::-webkit-scrollbar-track { background: var(--csdn-base); }
  ::-webkit-scrollbar-thumb {
    background: #30363d;
    border-radius: 6px;
    border: 3px solid var(--csdn-base);
  }
  ::-webkit-scrollbar-thumb:hover { background: #3d444d; }

  /* ---------- Selection ---------- */
  ::selection {
    background: #2d5986;
    color: #fff;
  }
}
